{
  "findings": [
    {
      "title": "Exclusion criterion 2 is misplaced and contradictory",
      "page": 34,
      "quote": "2. Lesion longest diameter at or above 2.4 cm.                    \na. Hemoglobin >18.0 g/dL",
      "severity": "critical"
    },
    {
      "title": "Inclusion criterion 5 lists sub-items starting with 'b' and includes an impossible hemoglobin value",
      "page": 34,
      "quote": "b. Absolute neutrophil count (ANC) >1.5 x 109/L \nc. Platelet count >75 x 109/L \nd. Serum creatinine <1.5 upper limit of normal (ULN) or estimated creatinine clearance (CrCl) >30 mL/min \ne. Adequate hepatic function: \n- Total bilirubin <1.5 x upper limit of normal (ULN) \n- Aspartate aminotransferase (AST) and alanine aminotransferase (ALT) both <3 x ULN \n- Alkaline phosphatase (ALP) <2.5 x ULN \nNote: For patients with Gilbert’s syndrome, total bilirubin ≤3x ULN.  Gilbert’s syndrome must be documented appropriately as past medical history.",
      "severity": "critical"
    },
    {
      "title": "Inclusion criterion 5 missing sub-item 'a' for hemoglobin",
      "page": 34,
      "quote": "5. Adequate organ and bone marrow function documented by: \nb. Absolute neutrophil count (ANC) >1.5 x 109/L",
      "severity": "major"
    },
    {
      "title": "Exclusion criterion 2 is incomplete and contradictory to inclusion criteria",
      "page": 34,
      "quote": "2. Lesion longest diameter at or above 2.4 cm.",
      "severity": "critical"
    },
    {
      "title": "Inclusion criterion 2 references UICC 9th edition which may not exist",
      "page": 33,
      "quote": "Note: Staging is per AJCC 8th edition for HN tumors (Amin, 2017) and is per UICC 9th edition for non-HN tumors (O'Sullivan, 2015).",
      "severity": "major"
    },
    {
      "title": "Inclusion criterion 2 states stage II to IV but study population section says stage III to IV with selected stage II",
      "page": 33,
      "quote": "Patients with stage III to stage IV (M0) CSCC of the head/neck, extremity, or trunk, and selected patients with stage II CSCC (≥3 cm longest diameter lesion in an aesthetically-sensitive region), for whom surgery is planned.",
      "severity": "major"
    },
    {
      "title": "Exclusion criterion 12 says prior systemic therapy within 3 years, but protocol likely intends shorter window",
      "page": 35,
      "quote": "12. Prior treatment with anti-cancer systemic therapy within the last 3 years prior to projected enrollment date",
      "severity": "minor"
    },
    {
      "title": "Exclusion criterion 4 allows physiologic replacement doses >10 mg prednisone, but criterion says condition requiring corticosteroid therapy >10 mg within 14 days",
      "page": 34,
      "quote": "4. Patients with a condition requiring corticosteroid therapy (>10 mg prednisone/day or equivalent) within 14 days of the first dose of study drug. \nExceptions: Physiologic replacement doses are allowed even if they are >10 mg of prednisone/day or equivalent, as long as they are not being administered for immunosuppressive intent.",
      "severity": "minor"
    },
    {
      "title": "Exclusion criterion 5 says autoimmune disease requiring systemic therapy within 5 years, but exception for childhood asthma that has resolved",
      "page": 35,
      "quote": "5. Patients with active, known, or suspected autoimmune disease that has required systemic therapy within 5 years of the projected enrollment date. \nExceptions: Patients with vitiligo, type I diabetes mellitus, and endocrinopathies (including hypothyroidism due to autoimmune thyroiditis) only requiring hormone replacement, childhood asthma that has resolved, or psoriasis that does not require systemic treatment are permitted.",
      "severity": "minor"
    },
    {
      "title": "Exclusion criterion 7 says 'uncontrolled infection with HIV, hepatitis B or hepatitis C' but then allows controlled infections",
      "page": 35,
      "quote": "7. Uncontrolled infection with human immunodeficiency virus (HIV), hepatitis B or hepatitis C virus (HBV or HCV) infection; or diagnosis of immunodeficiency",
      "severity": "minor"
    },
    {
      "title": "Exclusion criterion 16 says contraception for at least 6 months after last dose, but cemiplimab half-life may require longer",
      "page": 36,
      "quote": "16. Women of childbearing potential* and sexually active men who are unwilling to practice highly effective contraception prior to the first dose of study therapy, during the study, and for at least 6 months after the last dose.",
      "severity": "minor"
    },
    {
      "title": "Exclusion criterion 20 says diagnosis of squamous cell carcinoma of unknown primary, but study population includes CSCC of specific sites",
      "page": 36,
      "quote": "20. Diagnosis of squamous cell carcinoma of unknown (or occult) primary",
      "severity": "minor"
    }
  ]
}
